"""v4 upgrade/restore from a fixture generated by exact released v3.7.1 source."""
from contextlib import closing
import hashlib,json,os,sqlite3,subprocess,sys,tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parent
fixture=ROOT/'tests/fixtures/v371_baseline.sql';metadata=json.loads(fixture.with_suffix('.json').read_text())
assert hashlib.sha256(fixture.read_bytes()).hexdigest()==metadata['sha256']
with tempfile.TemporaryDirectory() as temporary:
 root=Path(temporary);source=root/'v371.sqlite';stage=root/'rehearsal';uploads=root/'uploads';uploads.mkdir()
 attachment=uploads/'preserved-fixture.txt';attachment.write_bytes(b'Fixture attachment must survive the upgrade.\n');digest=hashlib.sha256(attachment.read_bytes()).hexdigest()
 with closing(sqlite3.connect(source)) as original:
  original.executescript(fixture.read_text(encoding='utf-8'));original.execute('PRAGMA journal_mode=WAL');original.execute('PRAGMA wal_autocheckpoint=0')
  original.execute("INSERT INTO finance_settings VALUES('v4-wal-sentinel','Preserve uncheckpointed v3.7.1 write')");original.commit()
  before=list(original.iterdump());assert Path(str(source)+'-wal').exists()
  env={**os.environ,'APP_USERNAME':'fixture_admin','APP_PASSWORD':'','MLO_ATTACHMENT_DIR':str(uploads),'MLO_CREDENTIAL_KEY':'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=','SESSION_SECRET':'v4-upgrade-fixture-only','MLO_SCHEDULER_ENABLED':'false','MLO_CALENDAR_AUTO_SYNC':'false','MLO_SMTP_HOST':'','COOKIE_SECURE':'false'}
  result=subprocess.run([sys.executable,'-m','scripts.rehearse_v37','--source',str(source),'--work-dir',str(stage),'--legacy-owner-username','fixture_admin'],cwd=ROOT,env=env,capture_output=True,text=True,timeout=120)
  assert result.returncode==0,result.stdout+result.stderr
  report=json.loads(result.stdout);assert report['original_tables_preserved']==metadata['tables'];assert report['migration_idempotent'] and report['restoration_matches_baseline'];assert list(original.iterdump())==before
  with closing(sqlite3.connect(stage/'staging.sqlite')) as upgraded:
   assert upgraded.execute('PRAGMA foreign_key_check').fetchall()==[]
   assert upgraded.execute("SELECT name FROM sqlite_master WHERE name='mlo_bill_successors'").fetchone()
   assert upgraded.execute("SELECT value FROM finance_settings WHERE key='budget_name'").fetchone()[0]=='Preserved v3.7.1 plan'
   assert upgraded.execute("SELECT amount,frequency FROM finance_budget_rows WHERE section='income' AND name='Upgrade income'").fetchone()==(2000,'Biweekly')
   assert upgraded.execute("SELECT 1 FROM finance_merchant_rules WHERE category='Groceries' AND keyword='COSTCO WHOLESALE'").fetchone() is None
   assert upgraded.execute("SELECT name FROM life_courses WHERE code='V371'").fetchone()[0]=='Preserved imported course'
  assert hashlib.sha256(attachment.read_bytes()).hexdigest()==digest
 env['STUDY_NOTIFIER_DB']=str(stage/'staging.sqlite')
 check=r'''
from fastapi.testclient import TestClient
from app.main import app
from app.db import get_conn
from app.calendar_links import _decrypt
with TestClient(app,follow_redirects=False) as alice,TestClient(app,follow_redirects=False) as admin:
 assert alice.post('/login',data={'username':'alice','password':'UpgradeMemberPassword!123'}).status_code==303
 assert admin.post('/login',data={'username':'fixture_admin','password':'UpgradeFixturePassword!123'}).status_code==303
 assert alice.get('/life/tasks/1').status_code==200
 assert admin.get('/life/tasks/1').status_code==404
 assert admin.get('/finance/budget').status_code==200
 with get_conn() as db:
  uid=db.execute("SELECT id FROM users WHERE username='alice'").fetchone()[0]
  from app.v37 import read_user_setup
  setup=read_user_setup(db,uid)
  assert setup['timezone']=='Pacific/Kiritimati' and setup['theme']=='dark' and setup['palette']=='lavender'
  assert db.execute('SELECT COUNT(*) FROM life_files').fetchone()[0]>0
  token=db.execute('SELECT secret_blob FROM life_calendar_connections WHERE user_id=?',(uid,)).fetchone()
  import json
  assert json.loads(_decrypt(token[0]))['refresh_token']=='FAKE_FIXTURE_ONLY'
  assert alice.get('/life/files/1').content==b'Fixture attachment must survive the upgrade.\n'
  assert admin.get('/life/files/1').status_code==404
'''
 result=subprocess.run([sys.executable,'-c',check],cwd=ROOT,env=env,capture_output=True,text=True,timeout=60)
 assert result.returncode==0,result.stdout+result.stderr
 print(json.dumps({'source_version':metadata['version'],'source_commit':metadata['source_commit'],'synthetic':True,'production_verification':False,'tables_preserved':metadata['tables'],'wal_preserved':True,'source_unchanged':True,'migration_twice':True,'restored_identically':True,'attachment_sha256':digest}))
print('PASS v4 upgrade: exact-v3.7.1 synthetic fixture, all original columns/rows, WAL, preferences, Finance/rule deletion, private course, ownership, attachment and restoration.')
